"use client";

import { type ComponentPropsWithoutRef, type KeyboardEvent, type PointerEvent, forwardRef, useCallback, useEffect, useRef } from "react";
import { useResizablePanel } from "./resizable-panels-root";
import { clampSize, useIsomorphicLayoutEffect, useResizablePanels } from "./resizable-panels-state";
import { cn } from "@/lib/utils";

type HandleProps = ComponentPropsWithoutRef<"div"> & {
  /** The panel edge the handle sits on: its end (right or bottom) or its start (left or top). */
  side?: "start" | "end";
  /** Pixels moved by an arrow key. */
  step?: number;
  /** Pixels moved by an arrow key with Shift held. */
  largeStep?: number;
};

type Drag = { id: number; start: number; size: number; last: number; element: HTMLDivElement };

/** The draggable edge of a panel. Arrow keys resize it, Home and End go to its limits, and Escape cancels a drag. */
export const ResizableHandle = forwardRef<HTMLDivElement, HandleProps>(function ResizableHandle(
  { side = "end", step = 10, largeStep = 50, className, children, onKeyDown, onPointerDown, onPointerMove, onPointerUp, onPointerCancel, onLostPointerCapture, ...props },
  ref,
) {
  const group = useResizablePanels();
  const panel = useResizablePanel();
  const horizontal = group.direction === "horizontal";
  const fixed = panel.max <= panel.min;
  const disabled = group.disabled || panel.collapsed;
  const drag = useRef<Drag | null>(null);
  const latest = useRef(panel);
  useIsomorphicLayoutEffect(() => {
    latest.current = panel;
  });

  /** Whether moving right or down grows the panel. Right-to-left rows mirror the start and end edges. */
  const direction = (element: Element) => (side === "end" ? 1 : -1) * (horizontal && getComputedStyle(element).direction === "rtl" ? -1 : 1);
  const point = (event: PointerEvent) => (horizontal ? event.clientX : event.clientY);

  const finish = useCallback((cancel: boolean) => {
    const active = drag.current;
    if (!active) return;
    drag.current = null;
    if (cancel) latest.current.setSize(active.size);
    else if (active.last !== active.size) latest.current.commit(active.last);
    latest.current.setResizing(false);
    if (active.element.hasPointerCapture?.(active.id)) active.element.releasePointerCapture(active.id);
  }, []);

  useEffect(() => {
    if (!panel.resizing) return;
    const onKey = (event: globalThis.KeyboardEvent) => {
      if (event.key !== "Escape") return;
      event.preventDefault();
      event.stopPropagation();
      finish(true);
    };
    const onBlur = () => finish(true);
    const cursor = document.body.style.cursor;
    document.body.style.cursor = horizontal ? "col-resize" : "row-resize";
    window.addEventListener("keydown", onKey, true);
    window.addEventListener("blur", onBlur);
    return () => {
      document.body.style.cursor = cursor;
      window.removeEventListener("keydown", onKey, true);
      window.removeEventListener("blur", onBlur);
    };
  }, [panel.resizing, horizontal, finish]);

  useEffect(() => () => finish(true), [finish]);

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    onKeyDown?.(event);
    if (event.defaultPrevented || disabled) return;
    const amount = event.shiftKey ? largeStep : step;
    const keys: Record<string, number> = horizontal ? { ArrowLeft: -amount, ArrowRight: amount } : { ArrowUp: -amount, ArrowDown: amount };
    let next: number;
    if (event.key === "Home") next = panel.min;
    else if (event.key === "End") {
      if (!Number.isFinite(panel.max)) return;
      next = panel.max;
    } else if (keys[event.key] !== undefined) next = clampSize(panel.size + keys[event.key] * direction(event.currentTarget), panel.min, panel.max);
    else return;
    event.preventDefault();
    if (next === panel.size) return;
    panel.setSize(next);
    panel.commit(next);
  };

  return (
    <div
      ref={ref}
      role="separator"
      tabIndex={disabled ? undefined : 0}
      aria-label="Resize panel"
      aria-controls={panel.panelId}
      // The line runs across the direction panels are laid out in.
      aria-orientation={horizontal ? "vertical" : "horizontal"}
      aria-valuenow={panel.size}
      aria-valuemin={panel.min}
      aria-valuemax={Number.isFinite(panel.max) ? panel.max : undefined}
      aria-disabled={disabled || undefined}
      data-slot="resizable-handle"
      data-side={side}
      data-resizing={panel.resizing || undefined}
      hidden={panel.collapsed}
      className={cn(
        "group/handle absolute z-20 touch-none outline-none select-none",
        horizontal ? "inset-y-0 w-2 pointer-coarse:w-8" : "inset-x-0 h-2 pointer-coarse:h-8",
        !disabled && !fixed && (horizontal ? "cursor-col-resize" : "cursor-row-resize"),
        horizontal && (side === "end" ? "end-0 translate-x-1/2 rtl:-translate-x-1/2" : "start-0 -translate-x-1/2 rtl:translate-x-1/2"),
        !horizontal && (side === "end" ? "bottom-0 translate-y-1/2" : "top-0 -translate-y-1/2"),
        className,
      )}
      onKeyDown={handleKeyDown}
      onPointerDown={(event) => {
        onPointerDown?.(event);
        if (event.defaultPrevented || event.button !== 0 || disabled || fixed || drag.current) return;
        event.preventDefault();
        event.stopPropagation();
        if (event.pointerType !== "touch") event.currentTarget.focus({ preventScroll: true });
        drag.current = { id: event.pointerId, start: point(event), size: panel.size, last: panel.size, element: event.currentTarget };
        // Touch already has implicit capture on the pressed handle.
        if (event.pointerType !== "touch") event.currentTarget.setPointerCapture?.(event.pointerId);
        panel.setResizing(true);
      }}
      onPointerMove={(event) => {
        onPointerMove?.(event);
        const active = drag.current;
        if (!active || active.id !== event.pointerId) return;
        const next = clampSize(active.size + (point(event) - active.start) * direction(event.currentTarget), panel.min, panel.max);
        if (next === active.last) return;
        active.last = next;
        panel.setSize(next);
      }}
      onPointerUp={(event) => {
        onPointerUp?.(event);
        if (drag.current?.id === event.pointerId) finish(false);
      }}
      onPointerCancel={(event) => {
        onPointerCancel?.(event);
        if (drag.current?.id === event.pointerId) finish(true);
      }}
      onLostPointerCapture={(event) => {
        onLostPointerCapture?.(event);
        finish(true);
      }}
      {...props}
    >
      {children ?? (
        <span
          aria-hidden
          data-slot="resizable-line"
          className={cn(
            "pointer-events-none absolute bg-border transition-colors group-hover/handle:bg-ring group-focus-visible/handle:bg-foreground group-data-resizing/handle:bg-foreground group-aria-disabled/handle:bg-border motion-reduce:transition-none",
            horizontal ? "inset-y-0 left-1/2 w-px -translate-x-1/2" : "inset-x-0 top-1/2 h-px -translate-y-1/2",
          )}
        />
      )}
    </div>
  );
});

"use client";

import { forwardRef, useCallback, useContext, useId, useImperativeHandle, useMemo, useRef, useState, version } from "react";
import {
  type ResizablePanelContextValue,
  type ResizablePanelProps,
  type ResizablePanelsProps,
  ResizablePanelContext,
  ResizablePanelsContext,
  availableSize,
  clampSize,
  useIsomorphicLayoutEffect,
  useResizablePanels,
} from "./resizable-panels-state";
import { cn } from "@/lib/utils";

/** Panels in a row or stack. Give a panel a size to make it resizable; a panel without one fills what is left. */
export const ResizablePanels = forwardRef<HTMLDivElement, ResizablePanelsProps>(function ResizablePanels(
  { direction = "horizontal", minFillSize = 0, disabled = false, motion = true, className, ...props },
  ref,
) {
  const context = useMemo(() => ({ direction, minFillSize, disabled, animated: motion }), [direction, minFillSize, disabled, motion]);
  return (
    <ResizablePanelsContext.Provider value={context}>
      <div ref={ref} data-slot="resizable-panels" data-direction={direction} className={cn("flex size-full min-h-0 min-w-0 overflow-hidden", direction === "vertical" && "flex-col", className)} {...props} />
    </ResizablePanelsContext.Provider>
  );
});

/** One panel. Put a ResizableHandle inside it to resize it from that edge. */
export const ResizablePanel = forwardRef<HTMLDivElement, ResizablePanelProps>(function ResizablePanel(
  { size: sizeProp, defaultSize, minSize = 0, maxSize = Infinity, collapsed = false, onSizeChange, onSizeCommit, onResizingChange, id, className, style, children, ...props },
  ref,
) {
  const group = useResizablePanels();
  const { direction, minFillSize, animated } = group;
  const generatedId = useId();
  const panelId = id ?? generatedId;
  const element = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => element.current as HTMLDivElement);
  const sized = sizeProp !== undefined || defaultSize !== undefined;
  const [inner, setInner] = useState(defaultSize ?? 0);
  const [available, setAvailable] = useState(Infinity);
  const [resizing, setResizingState] = useState(false);
  const stored = sizeProp ?? inner;
  const max = Math.max(minSize, Math.min(maxSize, available));
  // The stored size is kept, so a panel squeezed by a small window returns to it when there is room.
  const size = clampSize(stored, minSize, max);
  const horizontal = direction === "horizontal";

  useIsomorphicLayoutEffect(() => {
    const panel = element.current;
    // Found from the DOM: a parent's ref is not attached yet when this first runs.
    const root = panel?.closest<HTMLElement>("[data-slot=resizable-panels]");
    if (!sized || !panel || !root) return;
    const measure = () => setAvailable(availableSize(panel, root, direction, minFillSize));
    measure();
    if (typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(measure);
    observer.observe(root);
    for (const child of root.children) if (child !== panel) observer.observe(child);
    return () => observer.disconnect();
  }, [sized, direction, minFillSize]);

  const latest = useRef({ controlled: sizeProp !== undefined, onSizeChange, onSizeCommit, onResizingChange });
  useIsomorphicLayoutEffect(() => {
    latest.current = { controlled: sizeProp !== undefined, onSizeChange, onSizeCommit, onResizingChange };
  });
  const setSize = useCallback((next: number) => {
    if (!latest.current.controlled) setInner(next);
    latest.current.onSizeChange?.(next);
  }, []);
  const commit = useCallback((next: number) => latest.current.onSizeCommit?.(next), []);
  const setResizing = useCallback((next: boolean) => {
    setResizingState(next);
    latest.current.onResizingChange?.(next);
  }, []);

  const context: ResizablePanelContextValue = { panelId, size, min: minSize, max, collapsed, resizing, setSize, commit, setResizing };
  const shown = collapsed ? 0 : size;
  // React 18 forwards inert as a string attribute. React 19 treats it as a boolean.
  const inertProps = collapsed ? { inert: version.startsWith("18.") ? "" as unknown as boolean : true, "aria-hidden": true } : {};

  return (
    <ResizablePanelContext.Provider value={context}>
      <div
        ref={element}
        id={panelId}
        data-slot="resizable-panel"
        data-sized={sized || undefined}
        data-collapsed={collapsed || undefined}
        data-resizing={resizing || undefined}
        className={cn(
          "relative min-h-0 min-w-0",
          sized ? "shrink-0" : "flex-1",
          collapsed && "overflow-hidden",
          sized && animated && !resizing && (horizontal ? "transition-[width] duration-200 ease-out motion-reduce:transition-none" : "transition-[height] duration-200 ease-out motion-reduce:transition-none"),
          className,
        )}
        style={sized ? { ...style, [horizontal ? "width" : "height"]: shown } : style}
        {...inertProps}
        {...props}
      >
        {children}
      </div>
    </ResizablePanelContext.Provider>
  );
});

export function useResizablePanel() {
  const context = useContext(ResizablePanelContext);
  if (!context) throw new Error("ResizableHandle must be rendered inside <ResizablePanel>.");
  return context;
}

"use client";

import { type ComponentPropsWithoutRef, createContext, useContext, useEffect, useLayoutEffect } from "react";

export const useIsomorphicLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

export type ResizablePanelsDirection = "horizontal" | "vertical";

export type ResizablePanelsProps = ComponentPropsWithoutRef<"div"> & {
  /** "horizontal" places panels side by side; "vertical" stacks them. */
  direction?: ResizablePanelsDirection;
  /** The space, in pixels, always left for the panel that fills. */
  minFillSize?: number;
  /** Turns off every handle. */
  disabled?: boolean;
  /** The collapse transition. Reduced motion is always honored. */
  motion?: boolean;
};

export type ResizablePanelProps = ComponentPropsWithoutRef<"div"> & {
  /** The panel's size in pixels, when your app owns it. Leave out both sizes for a panel that fills the remaining space. */
  size?: number;
  /** The starting size in pixels, when the panel keeps its own size. */
  defaultSize?: number;
  minSize?: number;
  maxSize?: number;
  /** Hides the panel and keeps its size for when it returns. */
  collapsed?: boolean;
  /** Called with live sizes while resizing. */
  onSizeChange?: (size: number) => void;
  /** Called once per finished drag or key press, for saving. */
  onSizeCommit?: (size: number) => void;
  /** Reports when a drag starts and ends. */
  onResizingChange?: (resizing: boolean) => void;
};

export type ResizablePanelsContextValue = {
  direction: ResizablePanelsDirection;
  minFillSize: number;
  disabled: boolean;
  animated: boolean;
};

export const ResizablePanelsContext = createContext<ResizablePanelsContextValue | null>(null);

export function useResizablePanels() {
  const context = useContext(ResizablePanelsContext);
  if (!context) throw new Error("ResizablePanel must be rendered inside <ResizablePanels>.");
  return context;
}

export type ResizablePanelContextValue = {
  panelId: string;
  size: number;
  min: number;
  max: number;
  collapsed: boolean;
  resizing: boolean;
  setSize: (size: number) => void;
  commit: (size: number) => void;
  setResizing: (resizing: boolean) => void;
};

export const ResizablePanelContext = createContext<ResizablePanelContextValue | null>(null);

export const clampSize = (size: number, min: number, max: number) => Math.round(Math.max(min, Math.min(Math.max(min, max), size)));

/** The most a panel can take: the group's size minus its sized neighbours and the space kept for the filling panel. */
export function availableSize(panel: HTMLElement, root: HTMLElement, direction: ResizablePanelsDirection, minFillSize: number) {
  const total = direction === "horizontal" ? root.clientWidth : root.clientHeight;
  if (total <= 0) return Infinity;
  const others = [...root.children].filter((child): child is HTMLElement => child !== panel && child instanceof HTMLElement && child.hasAttribute("data-sized"));
  return total - minFillSize - others.reduce((sum, child) => sum + (direction === "horizontal" ? child.offsetWidth : child.offsetHeight), 0);
}

"use client";

export { type ResizablePanelsProps, type ResizablePanelProps, type ResizablePanelsDirection } from "./resizable-panels-state";
export { ResizablePanels, ResizablePanel, useResizablePanel } from "./resizable-panels-root";
export { ResizableHandle } from "./resizable-panels-handle";
